import { FormEvent, ReactNode, useDeferredValue, useEffect, useRef, useState } from "react";
import { api, AudioDashboard, ChapterRow, Counts, del, Job, Model, OutputItem, post, put, ProductionManifest, ProductionPlan, QaResult, Scene, ScenesDashboard, StoryCard, StoryConfig, StoryDashboard, VideoDashboard } from "./api.js";
import { pretty } from "./format.js";
import { GlobalSettingsPage, LibraryPage, ManageStoryPage, NewStoryPage } from "./Milestone12.js";

type Route = { page: string; story?: string; chapter?: number };

export function App() {
  const [route, setRoute] = useState<Route>(() => parseRoute(location.pathname)); const [stories, setStories] = useState<StoryCard[]>([]); const [storiesError, setStoriesError] = useState(""); const [job, setJob] = useState<Job>();
  useEffect(() => { const handler = () => setRoute(parseRoute(location.pathname)); addEventListener("popstate", handler); return () => removeEventListener("popstate", handler); }, []);
  useEffect(() => { setStoriesError(""); api<{ stories: StoryCard[] }>("/stories").then((value) => setStories(value.stories)).catch((error) => { setStories([]); setStoriesError(message(error)); }); }, [route.page]);
  const navigate = (path: string) => { history.pushState({}, "", path); setRoute(parseRoute(path)); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const active = route.story ? stories.find((story) => story.slug === route.story) : undefined;
  return <div className="studio-shell">
    <Sidebar stories={stories} active={route.story} navigate={navigate} />
    <main className="canvas">
      <Topbar title={active?.title ?? pageTitle(route.page)} subtitle={active ? `${active.sourceLanguage} → ${active.outputLanguage}` : "Local production workspace"} />
      {route.page === "stories" && <LibraryPage stories={stories} error={storiesError} navigate={navigate} />}
      {route.page === "new" && <NewStoryPage navigate={navigate} />}
      {route.page === "app-settings" && <GlobalSettingsPage />}
      {route.page === "manage" && route.story && <ManageStoryPage slug={route.story} navigate={navigate} />}
      {route.page === "story" && route.story && <StoryPage slug={route.story} navigate={navigate} onJob={setJob} />}
      {route.page === "chapter" && route.story && route.chapter && <ChapterPage slug={route.story} chapter={route.chapter} navigate={navigate} />}
      {route.page === "qa" && route.story && <QaPage slug={route.story} navigate={navigate} />}
      {route.page === "preview" && route.story && <PreviewPage slug={route.story} onJob={setJob} />}
      {route.page === "bible" && route.story && <BiblePage slug={route.story} />}
      {route.page === "audio" && route.story && <AudioPage slug={route.story} onJob={setJob} />}
      {route.page === "video" && route.story && <VideoPage slug={route.story} onJob={setJob} />}
      {route.page === "scenes" && route.story && <ScenesPage slug={route.story} onJob={setJob} />}
      {route.page === "production" && route.story && <ProductionPage slug={route.story} activeJob={job?.type === "production" ? job : undefined} onJob={setJob} />}
      {route.page === "outputs" && route.story && <OutputsPage slug={route.story} />}
      {route.page === "voice" && route.story && <VoicePage slug={route.story} onJob={setJob} />}
      {route.page === "settings" && route.story && <SettingsPage slug={route.story} />}
      {route.page === "import" && <ImportPage stories={stories} navigate={navigate} />}
    </main>
    {job && <JobConsole job={job} onUpdate={setJob} onClose={() => setJob(undefined)} />}
  </div>;
}

function Sidebar({ stories, active, navigate }: { stories: StoryCard[]; active?: string; navigate: (path: string) => void }) {
  const storyPath = (suffix: string) => active ? `/stories/${active}${suffix}` : "/";
  return <aside className="sidebar">
    <button className="brand" onClick={() => navigate("/")}><span className="brand-mark">A</span><span><b>AI Story</b><small>Studio</small></span></button>
    <nav className="main-nav" aria-label="Studio navigation">
      <Nav icon="library" label="Stories" active={!active} onClick={() => navigate("/")} />
      <Nav icon="plus" label="New story" onClick={() => navigate("/new")} />
      <Nav icon="settings" label="App settings" onClick={() => navigate("/settings")} />
      <div className="nav-caption">Active story</div>
      <Nav icon="chapters" label="Chapters" disabled={!active} onClick={() => navigate(storyPath(""))} />
      <Nav icon="quality" label="Quality review" disabled={!active} onClick={() => navigate(storyPath("/qa"))} />
      <Nav icon="compare" label="Preview A/B" disabled={!active} onClick={() => navigate(storyPath("/preview"))} />
      <Nav icon="bible" label="Story Bible" disabled={!active} onClick={() => navigate(storyPath("/bible"))} />
      <Nav icon="scenes" label="Scenes / Artwork" disabled={!active} onClick={() => navigate(storyPath("/scenes"))} />
      <Nav icon="audio" label="Audio / Export" disabled={!active} onClick={() => navigate(storyPath("/audio"))} />
      <Nav icon="video" label="Video" disabled={!active} onClick={() => navigate(storyPath("/video"))} />
      <Nav icon="production" label="Production" disabled={!active} onClick={() => navigate(storyPath("/production"))} />
      <Nav icon="audio" label="Outputs" disabled={!active} onClick={() => navigate(storyPath("/outputs"))} />
      <Nav icon="audio" label="Voice test" disabled={!active} onClick={() => navigate(storyPath("/voice"))} />
      <Nav icon="settings" label="Settings" disabled={!active} onClick={() => navigate(storyPath("/settings"))} />
      <Nav icon="library" label="Manage project" disabled={!active} onClick={() => navigate(storyPath("/manage"))} />
    </nav>
    <div className="sidebar-stories"><div className="nav-caption">On the shelf</div>{stories.slice(0, 4).map((story) => <button key={story.slug} onClick={() => navigate(`/stories/${story.slug}`)} className={active === story.slug ? "active-story" : ""}><span>{story.title.slice(0, 1)}</span><div><b>{story.title}</b><small>{story.processedChapters} of {story.importedChapters} mixed</small></div></button>)}</div>
    <div className="system-ready"><i /> Local engine ready</div>
  </aside>;
}

function Nav({ icon, label, onClick, disabled, active }: { icon: string; label: string; onClick: () => void; disabled?: boolean; active?: boolean }) { return <button className={`nav-item ${active ? "active" : ""}`} disabled={disabled} onClick={onClick}><Icon name={icon} />{label}</button>; }
function Topbar({ title, subtitle }: { title: string; subtitle: string }) { return <header className="topbar"><div><span className="eyebrow">Production desk</span><h1>{title}</h1></div><div className="topbar-meta"><span>{subtitle}</span><kbd>⌘ K</kbd></div></header>; }

function StoriesPage({ stories, error, navigate }: { stories: StoryCard[]; error?: string; navigate: (path: string) => void }) {
  return <section className="page"><div className="section-heading"><div><h2>Your story shelf</h2><p>Open a production to review chapters, quality, and audio.</p></div><button className="button primary" onClick={() => navigate("/import")}><Icon name="plus" /> Import a story</button></div>
    {error ? <ErrorBox text={error} /> : stories.length ? <div className="story-grid">{stories.map((story) => <button className="story-card" key={story.slug} onClick={() => navigate(`/stories/${story.slug}`)}>
      <div className="card-top"><span className="source-chip">{story.sourceType}</span><span className="mono">{story.progress}%</span></div><h3>{story.title}</h3><p>{story.author ?? "Author not listed"}</p>
      <div className="reel" aria-label={`${story.progress}% processed`}>{["translation", "narration", "qa", "audio"].map((stage, index) => <i key={stage} className={story.progress >= (index + 1) * 25 ? "filled" : ""} />)}</div>
      <div className="card-stats"><span><b>{story.importedChapters}</b> chapters</span><span><b>{story.processedChapters}</b> processed</span><span><b>{story.qa.warn + story.qa.fail}</b> review</span></div>
      <div className="qa-line"><Status status="pass" label={`${story.qa.pass} pass`} /><Status status="warn" label={`${story.qa.warn} warn`} /><Status status="fail" label={`${story.qa.fail} fail`} /></div>{story.sourceUrl && <small className="source-url">{new URL(story.sourceUrl).hostname}</small>}
    </button>)}</div> : <Empty title="The shelf is waiting" text="Import a TXT, EPUB, DOCX, or Fanqie story to begin." action={<button className="button primary" onClick={() => navigate("/import")}>Import your first story</button>} />}
  </section>;
}

function StoryPage({ slug, navigate, onJob }: { slug: string; navigate: (path: string) => void; onJob: (job: Job) => void }) {
  const [overview, setOverview] = useState<StoryDashboard>(); const [page, setPage] = useState(1); const [filter, setFilter] = useState("all"); const [query, setQuery] = useState("");
  const deferredQuery = useDeferredValue(query);
  const [chapters, setChapters] = useState<{ items: ChapterRow[]; page: number; pages: number; total: number }>(); const [range, setRange] = useState({ from: "1", to: "10", force: "" }); const [error, setError] = useState(""); const [refreshResult, setRefreshResult] = useState<any>();
  useEffect(() => { api<StoryDashboard>(`/stories/${slug}/dashboard`).then((value) => { setOverview(value); setRange({ from: value.counts.minChapter ? String(value.counts.minChapter) : "", to: value.counts.maxChapter ? String(value.counts.maxChapter) : "", force: "" }); }).catch((e) => setError(message(e))); }, [slug]);
  useEffect(() => { api<any>(`/stories/${slug}/chapters?page=${page}&pageSize=50&filter=${filter}&q=${encodeURIComponent(deferredQuery)}`).then(setChapters).catch((e) => setError(e.message)); }, [slug, page, filter, deferredQuery]);
  const start = async () => { try { setError(""); const job = await post<Job>(`/stories/${slug}/jobs/batch`, { from: Number(range.from), to: Number(range.to), force: range.force || undefined }); onJob(job); } catch (e) { setError(message(e)); } };
  const refresh = async (importNew = false) => { try { const value = await post<any>(`/stories/${slug}/source/refresh`, { importNew }); setRefreshResult(value); if (importNew) alert(`Imported ${value.imported.length} new chapters.`); } catch (e) { setError(message(e)); } };
  if (!overview) return <Loading />;
  return <section className="page dashboard-page"><div className="dashboard-hero"><div><span className="eyebrow">Production dashboard</span><h2>{overview.story.title}</h2><p>{overview.story.author ?? "Author not listed"} · {overview.story.sourceLanguage} → {overview.story.outputLanguage} · {pretty(overview.story.source.type)} source</p><small>{overview.source ? `${overview.source.chapterCount} chapters imported ${new Date(overview.source.importedAt).toLocaleDateString()}` : "Source manifest unavailable"}</small></div><div className="quality-orbit"><strong>{overview.progress.processed}</strong><span>processed / {overview.counts.chapters}</span></div></div>
    <div className="dashboard-meter" aria-label="Story production progress">{Array.from({ length: Math.min(overview.counts.chapters, 60) }, (_, index) => { const ratio = overview.counts.chapters / Math.min(overview.counts.chapters, 60); const chapter = Math.floor(index * ratio) + 1; const level = chapter <= overview.progress.video ? "video" : chapter <= overview.progress.artwork ? "artwork" : chapter <= overview.progress.audio ? "audio" : chapter <= overview.progress.processed ? "text" : "imported"; return <i className={level} key={index} title={`Chapter ${chapter}: ${level}`} />; })}</div>
    <div className="dashboard-stats"><span><b>{overview.counts.chapters}</b>Imported</span><span><b>{overview.progress.processed}</b>Processed</span><span><b>{overview.counts.pass}/{overview.counts.warn}/{overview.counts.fail}</b>QA pass / warn / fail</span><span><b>{overview.progress.audio}</b>Audio</span><span><b>{overview.progress.artwork}</b>Artwork</span><span><b>{overview.progress.video}</b>Video</span><span><b>{overview.currentProfile ? pretty(overview.currentProfile) : "Not set"}</b>Current profile</span><span><b>{overview.estimatedRemainingStages}</b>Stage operations left</span></div>
    <div className="dashboard-actions"><button className="button primary" onClick={() => navigate(`/stories/${slug}/production`)}>Set up production</button><button className="button" onClick={() => navigate(`/stories/${slug}/production`)}>{overview.latestProduction?.status === "paused" ? "Resume production" : "Produce audiobook / video"}</button><button className="button" onClick={() => navigate("/import")}>Import / update chapters</button><button className="button" onClick={() => navigate(`/stories/${slug}/bible`)}>Open Story Bible</button><button className="button" onClick={() => navigate(`/stories/${slug}/outputs`)}>Browse outputs</button><button className="button" onClick={() => navigate(`/stories/${slug}/settings`)}>Open settings</button>{overview.story.source.type === "fanqie" && <button className="button" onClick={() => refresh(false)}>Check source</button>}</div>
    {overview.latestProduction && <div className="last-run"><span><b>Last production run</b></span><Status status={overview.latestProduction.status === "completed" ? "pass" : overview.latestProduction.status === "failed" ? "fail" : "warn"} label={pretty(overview.latestProduction.status)} /><span>{overview.latestProduction.summary.completed} complete · {formatDuration(overview.latestProduction.summary.elapsedMs / 1000)}</span></div>}
    {refreshResult && <div className="refresh-banner"><div><span className="eyebrow">Remote source</span><b>{refreshResult.previousImportedCount} imported · {refreshResult.currentCount} available</b><p>{refreshResult.added.length ? `New chapters: ${refreshResult.added.map((item: any) => item.chapter).join(", ")}` : "No new chapters found."}</p></div>{refreshResult.added.length > 0 && !refreshResult.imported.length && <button className="button primary" onClick={() => refresh(true)}>Import new chapters</button>}</div>}
    <div className="processing-panel"><div><span className="eyebrow">Start a batch</span><p>Choose a chapter range. Completed stages are reused unless forced.</p></div><Field label="From"><input value={range.from} onChange={(e) => setRange({ ...range, from: e.target.value })} inputMode="numeric" /></Field><Field label="To"><input value={range.to} onChange={(e) => setRange({ ...range, to: e.target.value })} inputMode="numeric" /></Field><Field label="Force stage"><select value={range.force} onChange={(e) => setRange({ ...range, force: e.target.value })}><option value="">Reuse valid work</option>{["translation", "narration", "qa", "story-bible", "tts", "audio", "all"].map((x) => <option key={x}>{x}</option>)}</select></Field><button className="button primary" onClick={start}>Start processing</button></div>
    {error && <ErrorBox text={error} />}
    <div className="table-tools"><div className="segmented">{[["all", "All"], ["unprocessed", "Unprocessed"], ["warn", "QA warn"], ["fail", "QA fail"], ["complete", "Complete"]].map(([value, label]) => <button className={filter === value ? "active" : ""} onClick={() => { setFilter(value); setPage(1); }} key={value}>{label}</button>)}</div><input className="search" placeholder="Find chapter or title" value={query} onChange={(e) => { setQuery(e.target.value); setPage(1); }} /></div>
    <div className="chapter-table"><div className="tr th"><span>Chapter</span><span>Translation</span><span>Narration</span><span>Quality</span><span>Mastered</span></div>{chapters?.items.map((chapter) => <button className="tr" key={chapter.chapter} onClick={() => navigate(`/stories/${slug}/chapters/${chapter.chapter}`)}><span><b>{String(chapter.chapter).padStart(4, "0")}</b><small>{chapter.originalTitle ?? "Untitled chapter"}</small></span><Stage value={chapter.translation} /><Stage value={chapter.narration} /><span>{chapter.qa ? <Status status={chapter.qa} label={`${chapter.qa}${chapter.qaScore !== undefined ? ` · ${Math.round(chapter.qaScore * 100)}` : ""}`} /> : <em>—</em>}</span><span><Stage value={chapter.audioMastering} />{chapter.durationSeconds && <small className="duration">{formatDuration(chapter.durationSeconds)}</small>}</span></button>)}</div>
    {chapters && <div className="pagination"><button disabled={chapters.page === 1} onClick={() => setPage(page - 1)}>Previous</button><span className="mono">Page {chapters.page} / {chapters.pages} · {chapters.total} chapters</span><button disabled={chapters.page === chapters.pages} onClick={() => setPage(page + 1)}>Next</button></div>}
  </section>;
}

function ChapterPage({ slug, chapter, navigate }: { slug: string; chapter: number; navigate: (path: string) => void }) {
  const [data, setData] = useState<any>(); const [error, setError] = useState(""); const [tab, setTab] = useState("compare"); const [draft, setDraft] = useState(""); const [saved, setSaved] = useState("");
  const load = () => api<any>(`/stories/${slug}/chapters/${chapter}`).then(setData);
  useEffect(() => { setData(undefined); setError(""); void load().catch((value) => setError(message(value))); }, [slug, chapter]);
  useEffect(() => { if (tab === "translation" || tab === "narration") setDraft(data?.[tab] ?? ""); }, [tab, data]);
  const saveText = async () => { try { setError(""); const result = await put<any>(`/stories/${slug}/chapters/${chapter}/text`, { field: tab, text: draft }); setSaved(`Saved. Regenerate: ${result.invalidated.map(pretty).join(", ")}.`); await load(); } catch (value) { setError(message(value)); } };
  if (error) return <LoadFailure error={error} />; if (!data) return <Loading />;
  return <section className="page reading-page"><div className="section-heading"><div><span className="eyebrow">Chapter {String(chapter).padStart(4, "0")}</span><h2>{data.metadata?.originalTitle ?? "Chapter review"}</h2></div>{data.qa && <Status status={data.qa.status} label={`${Math.round(data.qa.score * 100)} quality score`} />}</div>{data.stale && <ErrorBox text="The imported source changed. Reprocess this chapter before reviewing derived text or audio." />}
    <div className="tabs">{["compare", "original", "translation", "narration", "quality", "audio", "subtitles", "scenes", "artwork", "video"].map((name) => <button key={name} className={tab === name ? "active" : ""} onClick={() => { setTab(name); setSaved(""); }}>{name}</button>)}</div>
    {tab === "compare" && <div className="manuscript-split three"><Manuscript title="Original" text={data.original} /><Manuscript title="Translation" text={data.translation} /><Manuscript title="Narration" text={data.narration} /></div>}
    {tab === "original" && <Manuscript title="Original source" text={data.original} />}{(tab === "translation" || tab === "narration") && <div className="text-workspace"><div className="edit-warning"><b>Manual edit</b><span>Saving marks downstream artifacts stale. Paid stages will not run until you start production.</span></div><textarea value={draft} onChange={(event) => setDraft(event.target.value)} aria-label={`Edit ${tab}`} />{saved && <p className="save-note">{saved}</p>}<button className="button primary" disabled={!draft.trim() || draft === data[tab]} onClick={saveText}>Save {tab}</button></div>}
    {tab === "quality" && <QaDetail qa={data.qa} />}{tab === "audio" && <AudioDeck src={data.audioUrl} title={`Chapter ${chapter} master`} />}{tab === "subtitles" && (data.subtitles ? <pre className="subtitle-preview">{data.subtitles}</pre> : <Empty title="No subtitles yet" text="Generate subtitles from the Video workspace after mastering this chapter." />)}{(tab === "scenes" || tab === "artwork") && <Empty title={`Open ${tab} workspace`} text={`Review and edit Chapter ${chapter} ${tab} in the visual development workspace.`} action={<button className="button primary" onClick={() => navigate(`/stories/${slug}/scenes`)}>Open {tab}</button>} />}{tab === "video" && (data.videoUrl ? <video className="chapter-video-player" controls preload="metadata" src={data.videoUrl}><track kind="subtitles" src={data.subtitlesUrl} srcLang="en" label="English" /></video> : <Empty title="No chapter video yet" text="Render this chapter from the Video workspace." />)}
  </section>;
}

function QaPage({ slug, navigate }: { slug: string; navigate: (path: string) => void }) {
  const [data, setData] = useState<any>(); const [error, setError] = useState(""); const [status, setStatus] = useState("all");
  useEffect(() => { setData(undefined); setError(""); api(`/stories/${slug}/qa`).then(setData).catch((value) => setError(message(value))); }, [slug]);
  if (error) return <LoadFailure error={error} />; if (!data) return <Loading />;
  const chapters = data.chapters.filter((item: any) => status === "all" || item.status === status);
  return <section className="page"><div className="section-heading"><div><h2>Quality review</h2><p>Every concern is linked back to its chapter and evidence.</p></div></div><div className="qa-summary">{(["pass", "warn", "fail"] as const).map((key) => <button onClick={() => setStatus(key)} className={`qa-count ${key}`} key={key}><span>{key}</span><b>{data.counts[key]}</b><i /></button>)}</div>
    <div className="category-strip">{Object.entries(data.categories).map(([key, value]) => <span key={key}>{pretty(key)} <b>{String(value)}</b></span>)}</div>
    <div className="review-list">{chapters.map((item: any) => <button key={item.chapter} onClick={() => navigate(`/stories/${slug}/chapters/${item.chapter}`)}><div><span className="mono">CH {String(item.chapter).padStart(4, "0")}</span><h3>{item.title ?? `Chapter ${item.chapter}`}</h3><p>{item.issues[0]?.message ?? "No issues detected."}</p></div><Status status={item.status} label={`${Math.round(item.score * 100)} score`} /></button>)}</div>
  </section>;
}

function PreviewPage({ slug, onJob }: { slug: string; onJob: (job: Job) => void }) {
  const [story, setStory] = useState<StoryConfig>(); const [chapter, setChapter] = useState("1"); const [audio, setAudio] = useState(false); const [presets, setPresets] = useState<any>(); const [result, setResult] = useState<any>(); const [error, setError] = useState(""); const watcher = useRef<(() => void) | undefined>(undefined);
  useEffect(() => { setError(""); api<any>(`/stories/${slug}`).then(({ story }) => { setStory(story); const base = { translation: story.pipeline.translation, narration: story.pipeline.narration, qa: story.pipeline.qa, tts: story.pipeline.tts }; const other = story.pipeline.translation.provider === "gemini" ? "openai" : "gemini"; setPresets({ a: base, b: { ...base, translation: { provider: other, model: other === "openai" ? "gpt-5.6-terra" : "gemini-3.8-flash" } } }); }).catch((value) => setError(message(value))); return () => watcher.current?.(); }, [slug]);
  const run = async () => { try { setError(""); setResult(undefined); const job = await post<Job>(`/stories/${slug}/jobs/preview`, { chapter: Number(chapter), audioPreview: audio, presets }); onJob(job); watcher.current?.(); watcher.current = watchJob(job.id, async (next) => { onJob(next); if (next.status === "completed") setResult(await api(`/stories/${slug}/previews/${next.result.id}`)); else if (next.status === "failed") setError(next.error ?? "Preview failed"); }, (value) => setError(message(value))); } catch (e) { setError(message(e)); } };
  const choose = async (choice: "a" | "b") => { try { const response = await post<any>(`/stories/${slug}/profile`, { previewId: result.manifest.id, choice }); setStory(response.story); alert(`Option ${choice.toUpperCase()} is now the active story profile.`); } catch (e) { setError(message(e)); } };
  if (error && (!story || !presets)) return <LoadFailure error={error} />; if (!story || !presets) return <Loading />;
  return <section className="page"><div className="section-heading"><div><h2>Model audition</h2><p>One chapter, two production profiles. Canonical files stay untouched.</p><small className="active-profile">Active · {story.pipeline.translation.provider}/{story.pipeline.translation.model} translation · {story.pipeline.narration.provider}/{story.pipeline.narration.model} narration · {story.pipeline.qa.provider}/{story.pipeline.qa.model} QA</small></div><label className="toggle"><input type="checkbox" checked={audio} onChange={(e) => setAudio(e.target.checked)} /><span /> Short audio</label></div>
    <div className="preview-controls"><Field label="Chapter"><input value={chapter} onChange={(e) => setChapter(e.target.value)} /></Field><div className="preset-grid"><PresetEditor label="Option A · Current" value={presets.a} onChange={(value) => setPresets({ ...presets, a: value })} /><PresetEditor label="Option B · Challenger" value={presets.b} onChange={(value) => setPresets({ ...presets, b: value })} /></div><button className="button primary run-preview" onClick={run}>Run comparison</button></div>{error && <ErrorBox text={error} />}
    {result && <div className="comparison"><PreviewResult choice="a" result={result} onChoose={() => choose("a")} /><PreviewResult choice="b" result={result} onChoose={() => choose("b")} /></div>}
  </section>;
}

function ImportPage({ stories, navigate }: { stories: StoryCard[]; navigate: (path: string) => void }) {
  const [slug, setSlug] = useState(stories[0]?.slug ?? ""); const [mode, setMode] = useState<"file" | "url">("file"); const [file, setFile] = useState<File>(); const [url, setUrl] = useState(""); const [range, setRange] = useState({ from: "1", to: "10" }); const [inspection, setInspection] = useState<any>(); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  const inspect = async () => { setBusy(true); setError(""); try { if (mode === "url") setInspection(await post(`/stories/${slug}/source/inspect`, { url, from: Number(range.from), to: Number(range.to) })); else { if (!file) throw new Error("Select a source file first"); const buffer = await file.arrayBuffer(); setInspection(await api(`/stories/${slug}/source/inspect`, { method: "POST", body: buffer, headers: { "content-type": "application/octet-stream", "x-file-name": encodeURIComponent(file.name) } })); } } catch (e) { setError(message(e)); } finally { setBusy(false); } };
  const importIt = async () => { try { setBusy(true); await post(`/stories/${slug}/source/import`, { inspectionId: inspection.id, allowGaps: false }); navigate(`/stories/${slug}`); } catch (e) { setError(message(e)); setBusy(false); } };
  return <section className="page import-page"><div className="section-heading"><div><h2>Bring in a manuscript</h2><p>Inspect first. Nothing enters production until you confirm the detected chapters.</p></div></div><div className="import-stage"><div className="step-rail"><span className="active">Source</span><span className={inspection ? "active" : ""}>Inspect</span><span>Import</span></div><div className="import-form"><Field label="Story slug"><input value={slug} onChange={(e) => setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ""))} placeholder="undead-disaster" /></Field><div className="segmented"><button className={mode === "file" ? "active" : ""} onClick={() => setMode("file")}>TXT · EPUB · DOCX</button><button className={mode === "url" ? "active" : ""} onClick={() => setMode("url")}>Fanqie URL</button></div>{mode === "file" ? <label className="dropzone"><input type="file" accept=".txt,.epub,.docx" onChange={(e) => setFile(e.target.files?.[0])} /><Icon name="import" /><b>{file?.name ?? "Choose a manuscript"}</b><span>Up to 50 MB · parsed locally</span></label> : <><Field label="Fanqie URL"><input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://fanqienovel.com/page/…" /></Field><div className="field-row"><Field label="From chapter"><input value={range.from} onChange={(e) => setRange({ ...range, from: e.target.value })} /></Field><Field label="To chapter"><input value={range.to} onChange={(e) => setRange({ ...range, to: e.target.value })} /></Field></div></>}<button className="button primary" disabled={busy || !slug} onClick={inspect}>{busy ? "Inspecting…" : "Inspect source"}</button>{error && <ErrorBox text={error} />}</div>
    {inspection && <div className="inspection"><span className="eyebrow">Inspection ready</span><h3>{inspection.title ?? "Untitled source"}</h3><p>{inspection.author ?? "Unknown author"} · {inspection.type.toUpperCase()} · {inspection.chapterCount} selected{inspection.availableChapterCount > inspection.chapterCount ? ` of ${inspection.availableChapterCount} available` : ""}</p>{inspection.warnings.length > 0 && <ErrorBox text={inspection.warnings.map((x: any) => x.message).join(" · ")} />}<div className="detected-chapters">{inspection.chapters.slice(0, 8).map((item: any) => <span key={item.chapter}><b>{item.chapter}</b>{item.originalTitle ?? item.sourceTitle ?? "Chapter"}</span>)}</div><button className="button primary" onClick={importIt} disabled={busy}>Import {inspection.chapterCount} chapters</button></div>}</div></section>;
}

function BiblePage({ slug }: { slug: string }) { const [view, setView] = useState<any>(); const [error, setError] = useState(""); const [query, setQuery] = useState(""); const [category, setCategory] = useState("characters"); const [editing, setEditing] = useState<any>(); const sections = ["characters", "locations", "factions", "abilities", "classes", "ranks", "items", "creatures", "systemTerms", "relationships", "translationTerms"];
  const load = () => api<any>(`/stories/${slug}/story-bible`).then(setView); useEffect(() => { setView(undefined); setError(""); void load().catch((value) => setError(message(value))); }, [slug]);
  const beginAdd = () => setEditing({ category, value: newBibleValue(category) }); const save = async () => { try { setError(""); if (editing.id && !editing.id.startsWith("auto-")) await put(`/stories/${slug}/story-bible/${editing.id}`, { value: editing.value }); else await post(`/stories/${slug}/story-bible`, { category: editing.category, value: editing.value, replacementKey: editing.key }); setEditing(undefined); await load(); } catch (value) { setError(message(value)); } }; const remove = async (entry: any) => { if (!confirm(`Delete ${bibleEntryTitle(entry.value)}? This only changes the manual Bible overlay.`)) return; try { await del(`/stories/${slug}/story-bible/${entry.id}`); await load(); } catch (value) { setError(message(value)); } };
  if (error && !view) return <LoadFailure error={error} />; if (!view) return <Loading />; const entries = view.entries.filter((entry: any) => entry.category === category && JSON.stringify(entry.value).toLowerCase().includes(query.toLowerCase()));
  return <section className="page"><div className="section-heading"><div><h2>Story Bible</h2><p>Generated continuity with protected manual corrections.</p></div><div className="bible-tools"><input className="search" placeholder="Search entries" value={query} onChange={(e) => setQuery(e.target.value)} /><button className="button primary" onClick={beginAdd}>Add entry</button></div></div>{error && <ErrorBox text={error} />}<div className="bible-layout"><aside>{sections.map((section) => <button className={category === section ? "active" : ""} onClick={() => { setCategory(section); setEditing(undefined); }} key={section}>{pretty(section)} <b>{view.entries.filter((entry: any) => entry.category === section).length}</b></button>)}</aside><div className="bible-sections"><section><h3>{pretty(category)}</h3>{entries.length ? entries.map((entry: any) => <article key={entry.id}><div><b>{bibleEntryTitle(entry.value)}</b>{entry.manual && <span className="manual-badge">Manual</span>}</div><span>{entry.value.originalName ?? entry.value.original ?? entry.value.relationship}</span><p>{entry.value.description ?? entry.value.notes}</p><small className="mono">CH {entry.value.firstSeenChapter}—{entry.value.lastSeenChapter}</small><div className="entry-actions"><button onClick={() => setEditing(structuredClone(entry))}>{entry.manual ? "Edit" : "Correct"}</button><button onClick={() => remove(entry)}>Delete</button></div></article>) : <Empty title={`No ${pretty(category).toLowerCase()} yet`} text="Add a deliberate entry or let production extraction discover one." />}</section></div></div>{editing && <div className="editor-sheet"><div className="editor-sheet-head"><div><span className="eyebrow">{editing.id ? "Edit entry" : "New entry"}</span><h3>{pretty(editing.category)}</h3></div><button onClick={() => setEditing(undefined)} aria-label="Close editor">×</button></div><BibleFields category={editing.category} value={editing.value} onChange={(value) => setEditing({ ...editing, value })} /><div className="editor-sheet-actions"><button className="button" onClick={() => setEditing(undefined)}>Cancel</button><button className="button primary" onClick={save}>Save entry</button></div></div>}</section>;
}

function BibleFields({ category, value, onChange }: { category: string; value: any; onChange: (value: any) => void }) { const field = (key: string, label: string) => <Field label={label}><input value={value[key] ?? ""} onChange={(event) => onChange({ ...value, [key]: event.target.value })} /></Field>; return <div className="bible-form">{category === "relationships" ? <>{field("subject", "Subject")}{field("relationship", "Relationship")}{field("object", "Object")}</> : category === "translationTerms" ? <>{field("original", "Original term")}{field("canonicalEnglish", "Canonical English")}<Field label="Notes"><textarea value={value.notes ?? ""} onChange={(event) => onChange({ ...value, notes: event.target.value })} /></Field></> : <>{field("canonicalEnglishName", "Canonical English name")}{field("originalName", "Original name")}<Field label="Description"><textarea value={value.description ?? ""} onChange={(event) => onChange({ ...value, description: event.target.value })} /></Field></>}<div className="field-row"><Field label="First seen"><input type="number" min="1" value={value.firstSeenChapter} onChange={(event) => onChange({ ...value, firstSeenChapter: Number(event.target.value) })} /></Field><Field label="Last updated"><input type="number" min="1" value={value.lastSeenChapter} onChange={(event) => onChange({ ...value, lastSeenChapter: Number(event.target.value) })} /></Field></div></div>; }
function newBibleValue(category: string) { const chapters = { firstSeenChapter: 1, lastSeenChapter: 1 }; if (category === "relationships") return { subject: "", relationship: "", object: "", ...chapters }; if (category === "translationTerms") return { original: "", canonicalEnglish: "", notes: "", ...chapters }; return { canonicalEnglishName: "", originalName: "", description: "", ...(category === "characters" ? { aliases: [], pronouns: [] } : {}), ...chapters }; }
function bibleEntryTitle(value: any) { return value.canonicalEnglishName ?? value.canonicalEnglish ?? `${value.subject} → ${value.object}`; }

function ScenesPage({ slug, onJob }: { slug: string; onJob: (job: Job) => void }) {
  const [data, setData] = useState<ScenesDashboard>(); const [draft, setDraft] = useState<Scene[]>([]); const [range, setRange] = useState({ from: "", to: "" }); const [error, setError] = useState(""); const [estimate, setEstimate] = useState<number>(); const [saving, setSaving] = useState(false); const watcher = useRef<(() => void) | undefined>(undefined);
  const load = async (chapter?: number) => { const next = await api<ScenesDashboard>(`/stories/${slug}/scenes${chapter ? `?chapter=${chapter}` : ""}`); setData(next); setDraft(structuredClone(next.manifest?.scenes ?? [])); if (!range.from && next.selectedChapter) setRange({ from: String(next.selectedChapter), to: String(next.selectedChapter) }); };
  useEffect(() => { setData(undefined); setError(""); void load().catch((value) => setError(message(value))); return () => watcher.current?.(); }, [slug]);
  const chooseChapter = (chapter: number) => { setEstimate(undefined); setRange({ from: String(chapter), to: String(chapter) }); void load(chapter).catch((value) => setError(message(value))); };
  const run = async (kind: "scenes" | "artwork", extra: Record<string, unknown> = {}) => { try { setError(""); const job = await post<Job>(`/stories/${slug}/jobs/${kind}`, { from: Number(range.from), to: Number(range.to), ...extra }); onJob(job); watcher.current?.(); watcher.current = watchJob(job.id, async (next) => { onJob(next); if (next.status === "completed") { if (next.result?.dryRun) setEstimate(next.result.imageCountEstimate); await load(data?.selectedChapter); } else if (next.status === "failed") setError(next.error ?? `${pretty(kind)} job failed`); }, (value) => setError(message(value))); } catch (value) { setError(message(value)); } };
  const save = async () => { if (!data?.selectedChapter) return; try { setSaving(true); setError(""); await put(`/stories/${slug}/chapters/${data.selectedChapter}/scenes`, { scenes: draft }); await load(data.selectedChapter); } catch (value) { setError(message(value)); } finally { setSaving(false); } };
  const review = async (scene: Scene, value: Scene["artwork"]["review"]) => { if (!data?.selectedChapter) return; try { await post(`/stories/${slug}/chapters/${data.selectedChapter}/scenes/${scene.id}/review`, { review: value }); await load(data.selectedChapter); } catch (cause) { setError(message(cause)); } };
  const edit = (id: string, patch: Partial<Scene>) => setDraft((current) => current.map((scene) => scene.id === id ? { ...scene, ...patch } : scene));
  if (error && !data) return <LoadFailure error={error} />; if (!data) return <Loading />;
  return <section className="page scenes-page">
    <div className="section-heading"><div><span className="eyebrow">Visual development</span><h2>Scene reel</h2><p>Plan the chapter’s visual rhythm, direct each frame, then approve the artwork that enters video.</p></div><div className="scene-count"><b>{data.counts.planned}</b><span>chapters planned</span><small>{data.counts.artworkReady} with artwork</small></div></div>
    <div className="scene-toolbar"><Field label="Chapter"><select value={data.selectedChapter ?? ""} onChange={(event) => chooseChapter(Number(event.target.value))}>{data.chapters.map((chapter) => <option key={chapter.chapter} value={chapter.chapter}>{String(chapter.chapter).padStart(4, "0")} · {chapter.title ?? "Untitled"}</option>)}</select></Field><Field label="Range from"><input inputMode="numeric" value={range.from} onChange={(event) => setRange({ ...range, from: event.target.value })} /></Field><Field label="Range to"><input inputMode="numeric" value={range.to} onChange={(event) => setRange({ ...range, to: event.target.value })} /></Field><div className="scene-actions"><button className="button" onClick={() => run("scenes")}>Plan scenes</button><button className="button" onClick={() => run("artwork", { dryRun: true })}>Estimate images</button><button className="button primary" onClick={() => run("artwork")}>Generate missing artwork</button></div>{estimate !== undefined && <div className="cost-estimate"><b>{estimate}</b><span>paid image request{estimate === 1 ? "" : "s"}</span><small>Dry run only—nothing generated.</small></div>}</div>
    {error && <ErrorBox text={error} />}
    {data.manifest ? <>
      <div className="filmstrip" aria-label="Scene timing preview">{draft.map((scene) => <button key={scene.id} style={{ flexGrow: Math.max(1, scene.endSeconds - scene.startSeconds) }} className={`${scene.importance} ${scene.artwork.review}`} onClick={() => document.getElementById(scene.id)?.scrollIntoView({ behavior: "smooth" })}><i />{scene.imageUrl ? <img src={scene.imageUrl} alt="" /> : <span>{scene.id.replace("scene-", "")}</span>}<small>{formatTime(scene.startSeconds)}–{formatTime(scene.endSeconds)}</small></button>)}</div>
      <div className="scene-reel-head"><div><h3>Chapter {data.manifest.chapter} direction</h3><p>{data.manifest.manuallyEdited ? `Manual revision ${data.manifest.manualRevision}` : "Planner draft"} · {formatDuration(data.manifest.durationSeconds)}</p></div><button className="button primary" disabled={saving} onClick={save}>{saving ? "Saving…" : "Save scene edits"}</button></div>
      <div className="scene-cards">{draft.map((scene, index) => <article id={scene.id} key={scene.id} className={`scene-card ${scene.importance}`}><div className="scene-frame">{scene.imageUrl ? <img src={scene.imageUrl} alt={scene.summary} /> : <div><span>{String(index + 1).padStart(2, "0")}</span><small>Frame pending</small></div>}<span className={`review-flag ${scene.artwork.review}`}>{pretty(scene.artwork.review)}</span></div><div className="scene-copy"><header><div><span className="eyebrow">{scene.id}</span><h3>{formatTime(scene.startSeconds)} — {formatTime(scene.endSeconds)}</h3></div><Stage value={scene.artwork.status} /></header><Field label="Summary"><textarea value={scene.summary} onChange={(event) => edit(scene.id, { summary: event.target.value })} /></Field><div className="scene-fields"><Field label="Start seconds"><input type="number" step="0.001" min="0" value={scene.startSeconds} onChange={(event) => edit(scene.id, { startSeconds: Number(event.target.value) })} /></Field><Field label="End seconds"><input type="number" step="0.001" min="0" value={scene.endSeconds} onChange={(event) => edit(scene.id, { endSeconds: Number(event.target.value) })} /></Field><Field label="Importance"><select value={scene.importance} onChange={(event) => edit(scene.id, { importance: event.target.value as Scene["importance"] })}><option value="transition">Transition</option><option value="standard">Standard</option><option value="major">Major</option></select></Field></div><div className="scene-fields two"><Field label="Characters"><input value={scene.characters.join(", ")} onChange={(event) => edit(scene.id, { characters: event.target.value.split(",").map((value) => value.trim()).filter(Boolean) })} /></Field><Field label="Location"><input value={scene.location ?? ""} onChange={(event) => edit(scene.id, { location: event.target.value || undefined })} /></Field></div><Field label="Artwork prompt"><textarea className="prompt-editor" value={scene.visualPrompt} onChange={(event) => edit(scene.id, { visualPrompt: event.target.value })} /></Field><div className="scene-review"><button onClick={() => review(scene, "approved")} disabled={!scene.imageUrl}>Approve</button><button onClick={() => review(scene, "rejected")} disabled={!scene.imageUrl}>Reject</button><button onClick={() => review(scene, "needs-regeneration")} disabled={!scene.imageUrl}>Needs regeneration</button><button className="regenerate" onClick={() => run("artwork", { scene: scene.id, force: true })}>Regenerate frame</button></div>{scene.artwork.error && <small className="scene-error">{scene.artwork.error}</small>}</div></article>)}</div>
    </> : <Empty title="No scene plan yet" text="Choose one mastered chapter and plan its visual sequence. No artwork is generated during planning." action={<button className="button primary" onClick={() => run("scenes")}>Plan this chapter</button>} />}
  </section>;
}

function VideoPage({ slug, onJob }: { slug: string; onJob: (job: Job) => void }) {
  const [data, setData] = useState<VideoDashboard>(); const [range, setRange] = useState({ from: "", to: "", subtitleMode: "burn" as "none" | "burn" | "soft" | "both" }); const [error, setError] = useState(""); const watcher = useRef<(() => void) | undefined>(undefined);
  const load = async () => { const next = await api<VideoDashboard>(`/stories/${slug}/video`); setData(next); setRange((current) => ({ ...current, subtitleMode: next.settings.subtitleMode, ...(!current.from && next.chapters.length ? { from: String(next.chapters[0]!.chapter), to: String(next.chapters.at(-1)!.chapter) } : {}) })); };
  useEffect(() => { setData(undefined); setError(""); void load().catch((value) => setError(message(value))); return () => watcher.current?.(); }, [slug]);
  const run = async (kind: "subtitles" | "video" | "video-export") => { try { setError(""); const job = await post<Job>(`/stories/${slug}/jobs/${kind}`, { from: Number(range.from), to: Number(range.to), ...(kind === "video" ? { subtitleMode: range.subtitleMode } : {}) }); onJob(job); watcher.current?.(); watcher.current = watchJob(job.id, async (next) => { onJob(next); if (next.status === "completed") await load(); else if (next.status === "failed") setError(next.error ?? "Video job failed"); }, (value) => setError(message(value))); } catch (value) { setError(message(value)); } };
  if (error && !data) return <LoadFailure error={error} />; if (!data) return <Loading />;
  return <section className="page video-page"><div className="section-heading"><div><span className="eyebrow">Picture desk</span><h2>Chapter video editions</h2><p>Mastered narration becomes a restrained, readable screen edition.</p></div><div className="video-format-stamp">{data.settings.width}<i>×</i>{data.settings.height}<small>{data.settings.fps} FPS · H.264</small></div></div>
    <div className="render-rail"><span className={`rail-node ${data.counts.mastered ? "complete" : ""}`}><i>01</i><b>Mastered audio</b><small>{data.counts.mastered} / {data.counts.total}</small></span><span className={`rail-node ${data.counts.subtitles ? "complete" : ""}`}><i>02</i><b>Subtitle timing</b><small>{data.counts.subtitles} / {data.counts.total}</small></span><span className={`rail-node ${data.background.coverAvailable ? "complete" : "fallback"}`}><i>03</i><b>Visual field</b><small>{data.background.coverAvailable ? `${data.background.coverName} · ${data.background.effectiveMode}` : "Generated studio fallback"}</small></span><span className={`rail-node ${data.counts.videos ? "complete" : ""}`}><i>04</i><b>Chapter renders</b><small>{data.counts.videos} / {data.counts.total}</small></span></div>
    <div className="video-console"><div><span className="eyebrow">Render range</span><h3>Screen edition</h3><p>{data.settings.introDurationSeconds}s title card · CRF {data.settings.quality} · {pretty(data.settings.backgroundMode)}</p></div><Field label="From"><input value={range.from} onChange={(e) => setRange({ ...range, from: e.target.value })} /></Field><Field label="To"><input value={range.to} onChange={(e) => setRange({ ...range, to: e.target.value })} /></Field><Field label="Subtitles"><select value={range.subtitleMode} onChange={(e) => setRange({ ...range, subtitleMode: e.target.value as typeof range.subtitleMode })}><option value="burn">Burned in</option><option value="soft">Optional track</option><option value="both">Burned + track</option><option value="none">No subtitles</option></select></Field><div className="video-actions"><button className="button" onClick={() => run("subtitles")}>Generate subtitles</button><button className="button" onClick={() => run("video")}>Render chapters</button><button className="button primary" onClick={() => run("video-export")}>Build combined video</button></div></div>
    {error && <ErrorBox text={error} />}<div className="video-ledger"><section><div className="ledger-head"><h3>Render queue</h3><span className="mono">{data.counts.videos} ready</span></div>{data.chapters.map((chapter) => <article key={chapter.chapter}><span className="chapter-index">{String(chapter.chapter).padStart(4, "0")}</span><div><b>{chapter.title ?? `Chapter ${chapter.chapter}`}</b><small>{chapter.durationSeconds ? `${formatDuration(chapter.durationSeconds)} audio` : "Master audio first"}</small></div><Stage value={chapter.subtitleStatus} /><Stage value={chapter.videoStatus} />{chapter.videoAvailable ? <video controls preload="none" src={`/api/stories/${slug}/chapters/${chapter.chapter}/video`} /> : <span className="render-empty">—</span>}</article>)}</section><aside><h3>Combined editions</h3>{data.exports.length ? data.exports.map((item) => <a href={item.downloadUrl} download key={item.fingerprint}><span>MP4</span><div><b>Chapters {item.from}–{item.to}</b><small>{formatDuration(item.durationSeconds)} · {new Date(item.createdAt).toLocaleString()}</small></div><strong>↓</strong></a>) : <Empty title="No video edition yet" text="Render a range, then build one continuous MP4." />}</aside></div>
  </section>;
}

function AudioPage({ slug, onJob }: { slug: string; onJob: (job: Job) => void }) {
  const [data, setData] = useState<AudioDashboard>(); const [range, setRange] = useState({ from: "", to: "", format: "m4b" as "mp3" | "m4b" }); const [error, setError] = useState(""); const watcher = useRef<(() => void) | undefined>(undefined);
  const load = async () => { const next = await api<AudioDashboard>(`/stories/${slug}/audio`); setData(next); if (!range.from && next.chapters.length) setRange((current) => ({ ...current, from: String(next.chapters[0]!.chapter), to: String(next.chapters.at(-1)!.chapter) })); };
  useEffect(() => { setData(undefined); setError(""); void load().catch((value) => setError(message(value))); return () => watcher.current?.(); }, [slug]);
  const run = async (kind: "audio" | "audiobook") => { try { setError(""); const body = { from: Number(range.from), to: Number(range.to), ...(kind === "audiobook" ? { format: range.format } : {}) }; const job = await post<Job>(`/stories/${slug}/jobs/${kind}`, body); onJob(job); watcher.current?.(); watcher.current = watchJob(job.id, async (next) => { onJob(next); if (next.status === "completed") await load(); else if (next.status === "failed") setError(next.error ?? "Audio job failed"); }, (value) => setError(message(value))); } catch (value) { setError(message(value)); } };
  if (error && !data) return <LoadFailure error={error} />; if (!data) return <Loading />;
  return <section className="page audio-page"><div className="section-heading"><div><h2>Audio mastering &amp; export</h2><p>Polished chapter masters and bookmarkable audiobook editions.</p></div><Status status={data.counts.mastered === data.counts.total && data.counts.total ? "pass" : "pending"} label={`${data.counts.mastered} / ${data.counts.total} mastered`} /></div>
    <div className="audio-metrics"><article><span>Mastered chapters</span><b>{data.counts.mastered}</b></article><article><span>Total audiobook time</span><b>{formatDuration(data.totalDurationSeconds)}</b></article><article><span>Loudness target</span><b>{data.settings.loudnessTarget} <small>LUFS</small></b></article><article><span>True peak ceiling</span><b>{data.settings.truePeak} <small>dBTP</small></b></article></div>
    <div className="export-console"><div><span className="eyebrow">Build an edition</span><h3>{range.format.toUpperCase()} audiobook</h3><p>Missing chapter masters are created first. Existing TTS is reused.</p></div><Field label="From"><input value={range.from} inputMode="numeric" onChange={(e) => setRange({ ...range, from: e.target.value })} /></Field><Field label="To"><input value={range.to} inputMode="numeric" onChange={(e) => setRange({ ...range, to: e.target.value })} /></Field><Field label="Format"><select value={range.format} onChange={(e) => setRange({ ...range, format: e.target.value as "mp3" | "m4b" })}><option value="m4b">M4B · chapters + bookmarks</option><option value="mp3">MP3 · universal playback</option></select></Field><div className="export-actions"><button className="button" onClick={() => run("audio")}>Master missing chapters</button><button className="button primary" onClick={() => run("audiobook")}>Build audiobook</button></div></div>
    {error && <ErrorBox text={error} />}<div className="audio-layout"><section><h3>Chapter masters</h3><div className="master-list">{data.chapters.map((chapter) => <article key={chapter.chapter}><span className="mono">{String(chapter.chapter).padStart(4, "0")}</span><div><b>{chapter.title ?? `Chapter ${chapter.chapter}`}</b><small>{chapter.durationSeconds ? formatDuration(chapter.durationSeconds) : "Awaiting master"}</small></div><Stage value={chapter.status} />{chapter.audioAvailable && <audio controls preload="none" src={`/api/stories/${slug}/chapters/${chapter.chapter}/audio`} />}</article>)}</div></section><section><h3>Exports</h3><div className="export-list">{data.exports.length ? data.exports.map((item) => <a href={item.downloadUrl} key={item.fingerprint} download><span>{item.format.toUpperCase()}</span><div><b>Chapters {item.from}–{item.to}</b><small>{formatDuration(item.durationSeconds)} · {new Date(item.createdAt).toLocaleString()}</small></div><strong>↓</strong></a>) : <Empty title="No editions yet" text="Choose a range and build your first MP3 or M4B." />}</div></section></div>
  </section>;
}

function OutputsPage({ slug }: { slug: string }) {
  const [items, setItems] = useState<OutputItem[]>(); const [error, setError] = useState("");
  useEffect(() => { api<{ items: OutputItem[] }>("/stories/" + slug + "/outputs").then((value) => setItems(value.items)).catch((value) => setError(message(value))); }, [slug]);
  if (error) return <LoadFailure error={error} />; if (!items) return <Loading />;
  const groups: Array<[OutputItem["group"], string]> = [["chapterAudio", "Chapter audio"], ["audiobooks", "Audiobooks"], ["chapterVideos", "Chapter videos"], ["combinedVideos", "Combined videos"], ["subtitles", "Subtitles"], ["artwork", "Artwork"]];
  return <section className="page outputs-page"><div className="section-heading"><div><span className="eyebrow">Deliverables</span><h2>Outputs library</h2><p>Every finished file, served through validated local-file routes.</p></div><span className="mono">{items.length} files</span></div>{groups.map(([group, label]) => { const entries = items.filter((item) => item.group === group); return <section className="output-group" key={group}><div><h3>{label}</h3><span>{entries.length}</span></div>{entries.length ? <div className="output-grid">{entries.map((item) => <article key={item.id}><span className="format-stamp">{item.format.toUpperCase()}</span><div><b>{item.chapter ? "Chapter " + item.chapter : "Chapters " + item.from + "–" + item.to}</b><small>{formatBytes(item.bytes)} · {new Date(item.createdAt).toLocaleString()}{item.durationSeconds ? " · " + formatDuration(item.durationSeconds) : ""}</small></div><div>{["mp3", "m4b"].includes(item.format) && <a href={item.url}>Play</a>}{["mp4", "png"].includes(item.format) && <a href={item.url} target="_blank">View</a>}<a href={item.url} download>Download</a></div></article>)}</div> : <p className="empty-line">Nothing here yet. Production will place finished files here.</p>}</section>})}</section>;
}

function VoicePage({ slug, onJob }: { slug: string; onJob: (job: Job) => void }) {
  const demo = "The old city held its breath as dawn touched the rooftops. Somewhere beyond the walls, a bell began to ring.";
  const [story, setStory] = useState<StoryConfig>(); const [text, setText] = useState(demo); const [referenceId, setReferenceId] = useState(""); const [model, setModel] = useState(""); const [speed, setSpeed] = useState(1); const [audioUrl, setAudioUrl] = useState(""); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  useEffect(() => { api<any>("/stories/" + slug).then((value) => { setStory(value.story); setReferenceId(value.story.pipeline.tts.referenceId ?? ""); setModel(value.story.pipeline.tts.model); setSpeed(value.story.pipeline.tts.speed); }).catch((value) => setError(message(value))); }, [slug]);
  const generate = async () => { try { setBusy(true); setError(""); setAudioUrl(""); const job = await post<Job>("/stories/" + slug + "/jobs/voice-preview", { text, referenceId: referenceId || undefined, model, speed }); onJob(job); watchJob(job.id, (next) => { onJob(next); if (next.status === "completed") { setAudioUrl(next.result.audioUrl); setBusy(false); } else if (next.status === "failed") { setError(next.error ?? "Voice preview failed"); setBusy(false); } }, (value) => { setError(message(value)); setBusy(false); }); } catch (value) { setError(message(value)); setBusy(false); } };
  if (!story) return error ? <LoadFailure error={error} /> : <Loading />;
  return <section className="page voice-page"><div className="section-heading"><div><span className="eyebrow">Voice booth</span><h2>Test narration voice</h2><p>Preview files stay separate from chapter production and never change story fingerprints.</p></div><span className="paid-flag">May call Fish Audio</span></div><div className="voice-console"><div><Field label="Provider"><input value="Fish Audio" disabled /></Field><Field label="Model"><input value={model} onChange={(event) => setModel(event.target.value)} /></Field><Field label="Reference / voice ID"><input value={referenceId} onChange={(event) => setReferenceId(event.target.value)} /></Field><Field label={`Speed · ${speed.toFixed(2)}×`}><input type="range" min="0.5" max="2" step="0.05" value={speed} onChange={(event) => setSpeed(Number(event.target.value))} /></Field></div><div><Field label={"Sample text · " + text.length + "/1200"}><textarea value={text} maxLength={1200} onChange={(event) => setText(event.target.value)} /></Field><div className="voice-actions"><button className="button" onClick={() => setText(demo)}>Use demo narration</button><button className="button primary" disabled={busy || !text.trim()} onClick={generate}>{busy ? "Generating…" : "Generate voice preview"}</button></div></div></div>{error && <ErrorBox text={error} />}{audioUrl ? <AudioDeck src={audioUrl} title="Voice preview" /> : <Empty title="The booth is ready" text="Choose a voice, keep the sample short, then generate a standalone preview." />}</section>;
}

function SettingsPage({ slug }: { slug: string }) { const [story, setStory] = useState<StoryConfig>(); const [saved, setSaved] = useState(false); const [error, setError] = useState(""); useEffect(() => { setStory(undefined); setError(""); api<any>("/stories/" + slug).then((x) => setStory(x.story)).catch((value) => setError(message(value))); }, [slug]); if (error && !story) return <LoadFailure error={error} />; if (!story) return <Loading />;
  const save = async (event: FormEvent) => { event.preventDefault(); try { const response = await put<any>(`/stories/${slug}/settings`, { title: story.title, author: story.author, description: story.description, tags: story.tags, notes: story.notes, sourceLanguage: story.sourceLanguage, outputLanguage: story.outputLanguage, recentChapterSummaries: story.context.recentChapterSummaries, translation: story.pipeline.translation, narration: story.pipeline.narration, qa: story.pipeline.qa, scenePlanner: story.pipeline.scenePlanner, tts: { referenceId: story.pipeline.tts.referenceId, speed: story.pipeline.tts.speed }, audio: story.audio, subtitles: story.subtitles, video: story.video, scenes: story.scenes, artwork: story.artwork }); setStory(response.story); setSaved(true); setTimeout(() => setSaved(false), 2500); } catch (e) { setError(message(e)); } };
  const model = (key: "translation" | "narration" | "qa" | "scenePlanner", value: Model) => setStory({ ...story, pipeline: { ...story.pipeline, [key]: value } });
  const audio = (key: keyof StoryConfig["audio"], value: string | number) => setStory({ ...story, audio: { ...story.audio, [key]: value } });
  return <section className="page settings-page"><div className="section-heading"><div><h2>Story settings</h2><p>Credentials remain in the server environment and are never sent here.</p></div>{saved && <Status status="pass" label="Changes saved" />}</div><form onSubmit={save}><div className="settings-group"><h3>Manuscript</h3><Field label="Story title"><input value={story.title} onChange={(e) => setStory({ ...story, title: e.target.value })} /></Field><div className="field-row"><Field label="Source language"><input value={story.sourceLanguage} onChange={(e) => setStory({ ...story, sourceLanguage: e.target.value })} /></Field><Field label="Output language"><input value={story.outputLanguage} onChange={(e) => setStory({ ...story, outputLanguage: e.target.value })} /></Field></div><Field label="Recent summaries in context"><input type="number" min="0" max="100" value={story.context.recentChapterSummaries} onChange={(e) => setStory({ ...story, context: { recentChapterSummaries: Number(e.target.value) } })} /></Field></div><div className="settings-group"><h3>Model profile</h3>{(["translation", "narration", "qa"] as const).map((key) => <ModelEditor key={key} label={pretty(key)} value={story.pipeline[key]} onChange={(value) => model(key, value)} />)}</div><div className="settings-group"><h3>Voice</h3><Field label="Fish Audio reference"><input value={story.pipeline.tts.referenceId ?? ""} onChange={(e) => setStory({ ...story, pipeline: { ...story.pipeline, tts: { ...story.pipeline.tts, referenceId: e.target.value } } })} /></Field><Field label={`Speed · ${story.pipeline.tts.speed.toFixed(2)}×`}><input type="range" min="0.5" max="2" step="0.05" value={story.pipeline.tts.speed} onChange={(e) => setStory({ ...story, pipeline: { ...story.pipeline, tts: { ...story.pipeline.tts, speed: Number(e.target.value) } } })} /></Field></div><div className="settings-group"><h3>Audio master</h3><div className="field-row"><Field label="Loudness · LUFS"><input type="number" min="-24" max="-12" step="0.5" value={story.audio.loudnessTarget} onChange={(e) => audio("loudnessTarget", Number(e.target.value))} /></Field><Field label="True peak · dBTP"><input type="number" min="-6" max="-0.1" step="0.1" value={story.audio.truePeak} onChange={(e) => audio("truePeak", Number(e.target.value))} /></Field></div><div className="field-row"><Field label="Segment gap · sec"><input type="number" min="0" max="5" step="0.05" value={story.audio.segmentGapSeconds} onChange={(e) => audio("segmentGapSeconds", Number(e.target.value))} /></Field><Field label="Chapter gap · sec"><input type="number" min="0" max="10" step="0.1" value={story.audio.chapterGapSeconds} onChange={(e) => audio("chapterGapSeconds", Number(e.target.value))} /></Field></div><div className="field-row"><Field label="Bitrate"><select value={story.audio.bitrate} onChange={(e) => audio("bitrate", e.target.value)}>{["64k", "96k", "128k", "160k", "192k", "256k", "320k"].map((value) => <option key={value}>{value}</option>)}</select></Field><Field label="Sample rate"><select value={story.audio.sampleRate} onChange={(e) => audio("sampleRate", Number(e.target.value))}>{[32000, 44100, 48000].map((value) => <option key={value}>{value} Hz</option>)}</select></Field></div></div>{error && <ErrorBox text={error} />}<button className="button primary" type="submit">Save changes</button></form></section>;
}

function ProductionPage({ slug, activeJob, onJob }: { slug: string; activeJob?: Job; onJob: (job: Job) => void }) {
  const [story, setStory] = useState<StoryConfig>(); const [latest, setLatest] = useState<ProductionManifest>(); const [plan, setPlan] = useState<ProductionPlan>(); const [range, setRange] = useState({ from: "", to: "" }); const [allRange, setAllRange] = useState({ from: "", to: "" }); const [rangeMode, setRangeMode] = useState<"all" | "custom">("all"); const [profile, setProfile] = useState(""); const [outputs, setOutputs] = useState<string[]>([]); const [artwork, setArtwork] = useState(false); const [repairQa, setRepairQa] = useState(true); const [refresh, setRefresh] = useState(false); const [error, setError] = useState("");
  const reload = () => { void api<any>(`/stories/${slug}`).then((value) => { setStory(value.story); setProfile((current) => { if (current) return current; const next = value.story.defaultProductionProfile ?? "audiobook"; const defaults = value.story.productionProfiles[next]; if (defaults) { setOutputs(defaults.outputs); setArtwork(defaults.artwork); setRepairQa(defaults.repairQa); } return next; }); const imported = { from: String(value.counts.minChapter ?? ""), to: String(value.counts.maxChapter ?? "") }; setAllRange(imported); setRange((current) => current.from ? current : imported); }); void api<{ manifest?: ProductionManifest; latest?: ProductionManifest }>(`/stories/${slug}/production`).then((value) => setLatest(value.latest ?? value.manifest)); };
  useEffect(reload, [slug]); useEffect(() => { if (!activeJob || isTerminalJob(activeJob)) { reload(); return; } const timer = window.setInterval(reload, 1500); return () => clearInterval(timer); }, [activeJob?.id, activeJob?.status, slug]);
  const payload = (dryRun: boolean) => { const selectedRange = rangeMode === "all" ? allRange : range; return { from: Number(selectedRange.from), to: Number(selectedRange.to), profile: profile || undefined, outputs: outputs.length ? outputs : undefined, artwork, repairQa, refresh, dryRun }; };
  const preview = async () => { try { setError(""); setPlan(await post<ProductionPlan>(`/stories/${slug}/production/plan`, payload(true))); } catch (e) { setError(message(e)); } };
  const start = async (override?: { from: number; to: number }) => { if (!plan && !override) { setError("Review the production plan before starting."); return; } try { setError(""); onJob(await post<Job>(`/stories/${slug}/jobs/production`, { ...payload(false), ...override })); } catch (e) { setError(message(e)); } };
  const resume = async () => { if (!latest) return; try { setError(""); onJob(await post<Job>(`/stories/${slug}/jobs/production`, { from: latest.selection.from, to: latest.selection.to, ...latest.options, dryRun: false })); } catch (value) { setError(message(value)); } };
  const chooseProfile = (name: string) => { setProfile(name); const value = story?.productionProfiles[name]; if (value) { setOutputs(value.outputs); setArtwork(value.artwork); setRepairQa(value.repairQa); } setPlan(undefined); };
  const toggleOutput = (value: string) => setOutputs((current) => current.includes(value) ? current.filter((item) => item !== value) : [...current, value]);
  return <section className="page production-page"><div className="section-heading"><div><span className="eyebrow">End-to-end orchestrator</span><h2>Production run</h2><p>Plan, resume, and finish a chapter range through only the stages its outputs require.</p></div><div className="production-head-actions"><a className="button" href={"/stories/" + slug}>Story dashboard</a>{latest?.status === "paused" && <button className="button primary" onClick={resume}>Resume safely</button>}{latest && <Status status={latest.status === "completed" ? "pass" : latest.status.includes("error") ? "warn" : "pending"} label={pretty(latest.status)} />}</div></div>
    <div className="production-controls"><div className="production-options"><span>Chapter range</span><label><input type="radio" checked={rangeMode === "all"} onChange={() => setRangeMode("all")} /> All imported chapters</label><label><input type="radio" checked={rangeMode === "custom"} onChange={() => setRangeMode("custom")} /> Custom range</label></div>{rangeMode === "custom" && <><Field label="From"><input value={range.from} inputMode="numeric" onChange={(e) => { setRange({ ...range, from: e.target.value }); setPlan(undefined); }} /></Field><Field label="To"><input value={range.to} inputMode="numeric" onChange={(e) => { setRange({ ...range, to: e.target.value }); setPlan(undefined); }} /></Field></>}<Field label="Production profile"><select value={profile} onChange={(e) => chooseProfile(e.target.value)}>{Object.keys(story?.productionProfiles ?? { audio: true, audiobook: true, "story-video": true, everything: true }).map((name) => <option key={name} value={name}>{pretty(name)}</option>)}</select></Field><div className="production-options"><span>Final output</span>{["audio", "audiobook", "video"].map((value) => <label key={value}><input type="checkbox" checked={outputs.includes(value)} onChange={() => { toggleOutput(value); setPlan(undefined); }} /> {value === "audio" ? "Narrated chapters" : pretty(value)}</label>)}</div><div className="production-options"><span>Production options</span><label title="Attempts bounded text repair after a failed quality gate."><input type="checkbox" checked={repairQa} onChange={(e) => { setRepairQa(e.target.checked); setPlan(undefined); }} /> QA repair</label><label title="May call the configured paid image provider."><input type="checkbox" checked={artwork} onChange={(e) => { setArtwork(e.target.checked); setPlan(undefined); }} /> Artwork generation</label><label title="Included automatically for video output."><input type="checkbox" checked={outputs.includes("video")} readOnly /> Subtitle generation</label><label title="Included automatically for every narrated output."><input type="checkbox" checked readOnly /> Audio mastering</label><label><input type="checkbox" checked={refresh} onChange={(e) => { setRefresh(e.target.checked); setPlan(undefined); }} /> Check remote source first</label></div><button className="button primary" onClick={preview}>Review production plan</button></div>
    {error && <ErrorBox text={error} />}{plan && <div className="production-plan"><div className="section-heading"><div><h3>Review before production</h3><p>{plan.chapters.length} chapters · expected: {plan.finalOutputs.join(" · ")}</p></div><span className="mono">{plan.from}–{plan.to}</span></div><div className="plan-grid">{plan.stages.map((stage) => <article key={stage}><span>{pretty(stage)}</span><b>{plan.counts[stage]?.required ?? 0}</b><small>{plan.counts[stage]?.reusable ?? 0} cached</small></article>)}</div><p className="cost-note"><b>May call paid providers:</b> LLM {plan.estimates.llmOperations} · TTS {plan.estimates.ttsOperations} · artwork {plan.estimates.imageOperations}{plan.estimates.imagesPendingPlanning ? ` · ${plan.estimates.imagesPendingPlanning} chapters need scene plans before image totals are known` : ""}. Cached operations are free.</p><button className="button primary start-production" disabled={activeJob?.status === "running"} onClick={() => start()}>Start production</button></div>}
    {latest && <div className="production-run"><div className="run-head"><div><span className="eyebrow">{latest.status === "running" ? "Live production" : "Durable run record"}</span><h3>{latest.current.chapter ? "Chapter " + latest.current.chapter + " · " + pretty(latest.current.stage ?? "working") : pretty(latest.status)}</h3></div><b className="mono">{Math.round((latest.summary.completed + latest.summary.failed + latest.summary.needsReview) / Math.max(1, latest.summary.chapters) * 100)}%</b></div><div className="summary-strip"><span><b>{latest.summary.completed}</b> complete</span><span><b>{latest.summary.failed}</b> failed</span><span><b>{latest.summary.needsReview}</b> warnings</span><span><b>{latest.summary.reusedStages}</b> cached</span><span><b>{formatDuration(latest.summary.elapsedMs / 1000)}</b> running time</span></div><div className="production-table">{Object.values(latest.chapters).map((chapter) => <article key={chapter.chapter}><header><b>Chapter {chapter.chapter}</b><div><Status status={chapter.status === "complete" ? "pass" : chapter.status === "needs-review" ? "warn" : chapter.status === "failed" ? "fail" : "pending"} label={pretty(chapter.status)} />{chapter.status === "failed" && <><button onClick={() => start({ from: chapter.chapter, to: chapter.chapter })}>Retry</button><a href={"/stories/" + slug + "/chapters/" + chapter.chapter}>Open</a></>}</div></header><div>{Object.entries(chapter.operations).map(([stage, operation]) => <span key={stage} className={operation.status}><i />{pretty(stage)}{operation.reused ? " ↺" : ""}</span>)}</div></article>)}</div>{latest.failures.length > 0 && <div className="run-log"><h3>Warnings and failures</h3>{latest.failures.map((failure, index) => <p key={index}><span>{failure.chapter ? "Chapter " + failure.chapter : "Export"}</span>{pretty(failure.stage)} · {failure.message}</p>)}</div>}{Object.entries(latest.summary.exports).length > 0 && <div className="export-links">{latest.summary.exports.audiobook && <a className="button" href={`/api/stories/${slug}/exports/${latest.selection.from}-${latest.selection.to}.${latest.options.audiobookFormat}`}>Download audiobook</a>}{latest.summary.exports.video && <a className="button" href={`/api/stories/${slug}/video-exports/${latest.selection.from}-${latest.selection.to}.mp4`}>Download video</a>}</div>}</div>}
  </section>;
}

function JobConsole({ job, onUpdate, onClose }: { job: Job; onUpdate: (job: Job) => void; onClose: () => void }) { const [actionError, setActionError] = useState(""); useEffect(() => { if (isTerminalJob(job)) return; return watchJob(job.id, onUpdate, (value) => setActionError(message(value))); }, [job.id]); const stage = job.progress?.stage ?? job.progress?.event?.stage ?? job.progress?.type?.replace("chapter.", ""); const chapter = job.progress?.chapter;
  const pause = async () => { try { setActionError(""); await post(`/jobs/${job.id}/pause`, {}); } catch (error) { setActionError(message(error)); } };
  const label = ({ batch: "Processing chapters", preview: "Rendering comparison", audio: "Mastering chapter audio", audiobook: "Building audiobook", subtitles: "Timing subtitles", video: "Rendering chapter video", videoExport: "Building combined video", scenes: "Planning chapter scenes", artwork: "Generating scene artwork", production: "Producing finished story" } as Record<string, string>)[job.type] ?? "Working";
  return <aside className={`job-console ${job.status}`}><div className="job-head"><div><span className="live-dot" /><b>{label}</b></div><span className="mono">{job.status}</span></div><div className="job-progress"><i /><i /><i /><i /><i /></div><p>{actionError || job.error || (chapter ? `Chapter ${chapter} · ${pretty(stage ?? "working")}` : pretty(job.status))}</p><div className="job-actions">{job.status === "running" && ["batch", "audio", "audiobook", "subtitles", "video", "scenes", "artwork", "production"].includes(job.type) && <button onClick={() => void pause()}>Pause after chapter</button>}{["completed", "failed", "paused"].includes(job.status) && <button onClick={onClose}>Close</button>}</div></aside>;
}

function PresetEditor({ label, value, onChange }: { label: string; value: any; onChange: (value: any) => void }) { return <div className="preset"><span className="eyebrow">{label}</span>{(["translation", "narration", "qa"] as const).map((key) => <ModelEditor key={key} label={pretty(key)} value={value[key]} onChange={(next) => onChange({ ...value, [key]: next })} />)}</div>; }
function ModelEditor({ label, value, onChange }: { label: string; value: Model; onChange: (value: Model) => void }) { return <div className="model-editor"><label>{label}</label><select value={value.provider} onChange={(e) => onChange({ ...value, provider: e.target.value as Model["provider"] })}><option value="openai">OpenAI</option><option value="gemini">Gemini</option></select><input value={value.model} onChange={(e) => onChange({ ...value, model: e.target.value })} /></div>; }
function PreviewResult({ choice, result, onChoose }: { choice: "a" | "b"; result: any; onChoose: () => void }) { const qa = result[choice === "a" ? "qaA" : "qaB"]; return <article className="preview-result"><div className="preview-result-head"><span className="option-letter">{choice.toUpperCase()}</span><Status status={qa.status} label={`${Math.round(qa.score * 100)} score`} /></div><Manuscript title="Translation" text={result[choice === "a" ? "translationA" : "translationB"]} compact /><Manuscript title="Narration" text={result[choice === "a" ? "narrationA" : "narrationB"]} compact />{result[choice === "a" ? "audioA" : "audioB"] && <AudioDeck src={`/api/stories/${result.manifest.story}/previews/${result.manifest.id}/audio-${choice}`} title={`Option ${choice.toUpperCase()} sample`} />}<button className="button primary" onClick={onChoose}>Use option {choice.toUpperCase()}</button></article>; }
function Manuscript({ title, text, compact }: { title: string; text?: string; compact?: boolean }) { return <article className={`manuscript ${compact ? "compact" : ""}`}><header><span>{title}</span><small className="mono">{text?.split(/\s+/).filter(Boolean).length ?? 0} words</small></header><div>{text ? text.split(/\n\n+/).map((paragraph, index) => <p key={index}>{paragraph}</p>) : <p className="empty-line">This stage has not produced text yet.</p>}</div></article>; }
function QaDetail({ qa }: { qa?: QaResult }) { if (!qa) return <Empty title="No quality review yet" text="Process this chapter through the QA stage to see findings." />; return <div className="qa-detail"><div className="score-card"><Status status={qa.status} label={qa.status} /><b className="mono">{Math.round(qa.score * 100)}</b><span>quality score</span></div><div className="checks">{Object.entries(qa.checks).map(([key, value]) => <div key={key}><span>{pretty(key)}</span><Status status={value} label={value} /></div>)}</div><div className="issues">{qa.issues.map((issue, index) => <article key={index}><Status status={issue.severity} label={pretty(issue.category)} /><h3>{issue.message}</h3><blockquote>{issue.evidence}</blockquote></article>)}</div></div>; }
function AudioDeck({ src, title }: { src?: string; title: string }) { const ref = useRef<HTMLAudioElement>(null); const [playing, setPlaying] = useState(false); if (!src) return <Empty title="No audio master" text="Audio becomes available after TTS completes." />; return <div className="audio-deck"><button onClick={() => { if (playing) ref.current?.pause(); else void ref.current?.play(); setPlaying(!playing); }}>{playing ? "Ⅱ" : "▶"}</button><div><b>{title}</b><div className="waveform">{Array.from({ length: 42 }, (_, i) => <i style={{ height: `${18 + (i * 17 % 32)}%` }} key={i} />)}</div></div><audio ref={ref} src={src} onEnded={() => setPlaying(false)} /></div>; }
function Stage({ value = "pending" }: { value?: string }) { return <span className={`stage ${value}`}><i />{value === "complete" ? "Complete" : pretty(value)}</span>; }
function Status({ status, label }: { status: string; label: string }) { return <span className={`status ${status}`}><i />{label}</span>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="field"><span>{label}</span>{children}</label>; }
function Loading() { return <div className="loading"><i /><i /><i /></div>; }
function LoadFailure({ error }: { error: string }) { return <section className="page"><ErrorBox text={error} /><button className="button" onClick={() => location.reload()}>Retry</button></section>; }
function ErrorBox({ text }: { text: string }) { return <div className="error-box"><Icon name="quality" /><span>{text}</span></div>; }
function Empty({ title, text, action }: { title: string; text: string; action?: ReactNode }) { return <div className="empty"><span className="empty-glyph">¶</span><h3>{title}</h3><p>{text}</p>{action}</div>; }
function Icon({ name }: { name: string }) { const paths: Record<string, string> = { library: "M4 5.5h5v13H4zM11 5.5h5v13h-5zM18 7h2v11.5h-2z", import: "M12 3v12m0 0 4-4m-4 4-4-4M4 19h16", chapters: "M5 4h12a2 2 0 0 1 2 2v14H7a2 2 0 0 1-2-2zM5 7h14M9 4v16", quality: "M12 3 4 6v5c0 5 3.5 8 8 10 4.5-2 8-5 8-10V6zM9 12l2 2 4-5", compare: "M8 4H4v16h4M16 4h4v16h-4M8 12h8", audio: "M4 15V9m4 9V6m4 15V3m4 15V6m4 9V9", video: "M4 6h11v12H4zM15 10l5-3v10l-5-3z", production: "M4 18V6l8-3 8 3v12l-8 3zM8 8h8M8 12h8M8 16h5", bible: "M4 5.5A3.5 3.5 0 0 1 7.5 2H12v18H7.5A3.5 3.5 0 0 0 4 23zM20 5.5A3.5 3.5 0 0 0 16.5 2H12v18h4.5A3.5 3.5 0 0 1 20 23z", settings: "M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM4 12H2m20 0h-2M12 4V2m0 20v-2M6.3 6.3 4.9 4.9m14.2 14.2-1.4-1.4M17.7 6.3l1.4-1.4M4.9 19.1l1.4-1.4", plus: "M12 5v14M5 12h14" }; return <svg viewBox="0 0 24 24" aria-hidden="true"><path d={paths[name] ?? paths.library} /></svg>; }
function parseRoute(path: string): Route { const parts = path.split("/").filter(Boolean); if (!parts.length) return { page: "stories" }; if (parts[0] === "new") return { page: "new" }; if (parts[0] === "settings") return { page: "app-settings" }; if (parts[0] === "import") return { page: "import" }; if (parts[0] !== "stories" || !parts[1]) return { page: "stories" }; if (parts[2] === "chapters" && parts[3]) return { page: "chapter", story: parts[1], chapter: Number(parts[3]) }; if (["qa", "preview", "bible", "audio", "video", "scenes", "production", "outputs", "voice", "settings", "manage"].includes(parts[2] ?? "")) return { page: parts[2]!, story: parts[1] }; return { page: "story", story: parts[1] }; }
function pageTitle(page: string) { return ({ stories: "AI Story Studio", import: "Import", new: "New Story", "app-settings": "Studio Settings" } as Record<string, string>)[page] ?? pretty(page); }
function message(error: unknown) { return error instanceof Error ? error.message : String(error); }
function formatDuration(seconds: number) { if (!Number.isFinite(seconds) || seconds <= 0) return "0:00"; const whole = Math.round(seconds); const hours = Math.floor(whole / 3600); const minutes = Math.floor(whole % 3600 / 60); const rest = whole % 60; return hours ? `${hours}:${String(minutes).padStart(2, "0")}:${String(rest).padStart(2, "0")}` : `${minutes}:${String(rest).padStart(2, "0")}`; }
function formatBytes(bytes: number) { if (bytes < 1024) return `${bytes} B`; if (bytes < 1024 ** 2) return `${(bytes / 1024).toFixed(1)} KB`; return `${(bytes / 1024 ** 2).toFixed(1)} MB`; }
function formatTime(seconds: number) { const minutes = Math.floor(Math.max(0, seconds) / 60); const rest = Math.floor(Math.max(0, seconds) % 60); return `${minutes}:${String(rest).padStart(2, "0")}`; }

function isTerminalJob(job: Job) { return ["completed", "failed", "paused"].includes(job.status); }
function watchJob(id: string, onUpdate: (job: Job) => void | Promise<void>, onError: (error: unknown) => void) {
  let stopped = false; let timer: number | undefined; const source = new EventSource(`/api/jobs/${id}/events`);
  const deliver = (job: Job) => { void Promise.resolve(onUpdate(job)).catch(onError); if (isTerminalJob(job)) stop(); };
  const poll = async () => {
    if (stopped) return;
    try { const job = await api<Job>(`/jobs/${id}`); deliver(job); if (!isTerminalJob(job)) timer = window.setTimeout(poll, 1000); }
    catch (error) { onError(error); timer = window.setTimeout(poll, 2000); }
  };
  source.addEventListener("job", (event) => { try { deliver(JSON.parse((event as MessageEvent).data) as Job); } catch (error) { onError(error); } });
  source.onerror = () => { if (stopped) return; source.close(); void poll(); };
  function stop() { if (stopped) return; stopped = true; source.close(); if (timer !== undefined) clearTimeout(timer); }
  return stop;
}
